import{_ as o,o as e,c as l,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"Ceph Developer Monthly | 2025-02-12","description":"","frontmatter":{"title":"Ceph Developer Monthly | 2025-02-12","date":"2025-02-12T00:00:00.000Z","updated":"2025-04-03T00:00:00.000Z","tags":["Ceph","分布式存储","健康检查","日志忽略列表","Boost JSON","S3 测试维护"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Ceph_Developer_Monthly_2025-02-12.md","filePath":"posts/2025/Ceph_Developer_Monthly_2025-02-12.md","lastUpdated":1780460162000}'),r={name:"posts/2025/Ceph_Developer_Monthly_2025-02-12.md"};function a(i,t,n,h,p,_){return e(),l("div",null,[...t[0]||(t[0]=[s('<h3 id="会议纪要-ceph-开发月度会议-cdm" tabindex="-1">会议纪要：Ceph 开发月度会议（CDM） <a class="header-anchor" href="#会议纪要-ceph-开发月度会议-cdm" aria-label="Permalink to &quot;会议纪要：Ceph 开发月度会议（CDM）&quot;">​</a></h3><p><strong>日期</strong>: 2025-02-12<br><strong>主持人</strong>: Ilia Mirkin<br><strong>参会人员</strong>: Patrick, Casey, Ratuslaf, Elliot, Adam, Laura 等</p><h4 id="_1-日志忽略列表问题讨论" tabindex="-1">1. 日志忽略列表问题讨论 <a class="header-anchor" href="#_1-日志忽略列表问题讨论" aria-label="Permalink to &quot;1. 日志忽略列表问题讨论&quot;">​</a></h4><ul><li><strong>问题背景</strong>: 升级测试套件中，某些健康检查被错误触发，导致复杂的日志忽略列表机制。</li><li><strong>问题描述</strong>: 健康检查描述字符串自由形式，需多次运行测试以确定所有需要忽略的字符串。</li><li><strong>解决方案讨论</strong>: <ol><li>使用<code>health mute</code>命令直接忽略特定健康检查。</li><li>引入健康检查宽限期，避免在特定操作期间触发警告。</li><li>审计现有健康检查，确定哪些检查可以受益于宽限期。</li></ol></li><li><strong>后续行动</strong>: <ul><li>创建相关任务来处理健康忽略列表和健康检查审计。</li><li>由Ilia负责创建相关任务并通知相关组件负责人。</li></ul></li></ul><h4 id="_2-迁移seth-jason从boost-spirit到boost-json" tabindex="-1">2. 迁移Seth Jason从Boost Spirit到Boost JSON <a class="header-anchor" href="#_2-迁移seth-jason从boost-spirit到boost-json" aria-label="Permalink to &quot;2. 迁移Seth Jason从Boost Spirit到Boost JSON&quot;">​</a></h4><ul><li><strong>背景</strong>: Boost Spirit和Boost MPL等库维护不善，与现代C++标准不兼容。</li><li><strong>解决方案</strong>: 将Seth Jason中的Boost Spirit替换为Boost JSON，提高性能和代码可维护性。</li><li><strong>后续行动</strong>: <ul><li>Adam将继续推进此项工作，并在RGW测试通过后通知其他子系统维护者进行审查和测试。</li></ul></li></ul><h4 id="_3-s3测试仓库的维护问题" tabindex="-1">3. S3测试仓库的维护问题 <a class="header-anchor" href="#_3-s3测试仓库的维护问题" aria-label="Permalink to &quot;3. S3测试仓库的维护问题&quot;">​</a></h4><ul><li><strong>背景</strong>: S3测试仓库维护复杂，需要确保测试分支与代码分支同步。</li><li><strong>讨论</strong>: 将S3测试合并到Ceph源代码中，以简化维护流程。</li><li><strong>后续行动</strong>: <ul><li>计划向开发邮件列表发送邮件，征求社区意见。</li><li>考虑将S3测试合并到Ceph源代码中，并删除Ceph不感兴趣的部分。</li></ul></li></ul><p><strong>会议结束</strong></p>',9)])])}const u=o(r,[["render",a]]);export{g as __pageData,u as default};
